from roman import to_roman, from_roman
import re
import string

import pytest
from hypothesis import given, assume
import hypothesis.strategies as st


# ---- obviously-correct reference model (digit tables) ----
_TH = ["", "M", "MM", "MMM"]
_H = ["", "C", "CC", "CCC", "CD", "D", "DC", "DCC", "DCCC", "CM"]
_T = ["", "X", "XX", "XXX", "XL", "L", "LX", "LXX", "LXXX", "XC"]
_O = ["", "I", "II", "III", "IV", "V", "VI", "VII", "VIII", "IX"]

def ref_to_roman(n: int) -> str:
    return _TH[n // 1000] + _H[(n % 1000) // 100] + _T[(n % 100) // 10] + _O[n % 10]

CANONICAL_SET = {ref_to_roman(n): n for n in range(1, 4000)}


# ---- spec examples ----
def test_example_to_roman_4():
    assert to_roman(4) == "IV"

def test_example_to_roman_1994():
    assert to_roman(1994) == "MCMXCIV"

def test_example_to_roman_3999():
    assert to_roman(3999) == "MMMCMXCIX"

def test_example_from_roman_lviii():
    assert from_roman("LVIII") == 58

def test_example_from_roman_iiii_raises():
    with pytest.raises(ValueError):
        from_roman("IIII")

def test_example_to_roman_0_raises():
    with pytest.raises(ValueError):
        to_roman(0)


# ---- invariants / round-trips ----
@given(st.integers(min_value=1, max_value=3999))
def test_roundtrip_from_to(n):
    assert from_roman(to_roman(n)) == n

@given(st.integers(min_value=1, max_value=3999))
def test_roundtrip_to_from(n):
    s = to_roman(n)
    assert to_roman(from_roman(s)) == s

@given(st.integers(min_value=1, max_value=3999))
def test_to_roman_matches_reference(n):
    assert to_roman(n) == ref_to_roman(n)

@given(st.integers(min_value=1, max_value=3999))
def test_from_roman_matches_reference(n):
    assert from_roman(ref_to_roman(n)) == n

@given(st.integers(min_value=1, max_value=3999))
def test_from_roman_result_in_range(n):
    r = from_roman(to_roman(n))
    assert isinstance(r, int) and not isinstance(r, bool)
    assert 1 <= r <= 3999

def test_exhaustive_roundtrip_all():
    for n in range(1, 4000):
        assert from_roman(to_roman(n)) == n
        assert to_roman(from_roman(ref_to_roman(n))) == ref_to_roman(n)

def test_to_roman_result_is_canonical_uppercase():
    allowed = set("IVXLCDM")
    for n in (1, 2, 3, 4, 5, 9, 14, 40, 44, 90, 400, 900, 944, 1994, 3999):
        s = to_roman(n)
        assert s == s.upper()
        assert len(s) > 0
        assert set(s) <= allowed


# ---- to_roman type errors ----
@pytest.mark.parametrize("bad", [True, False, 1.0, 4.0, "IV", "4", None, [4], (4,), b"IV", 4.5])
def test_to_roman_type_errors(bad):
    with pytest.raises(TypeError):
        to_roman(bad)

@given(st.floats(allow_nan=False, allow_infinity=False) | st.text(max_size=5))
def test_to_roman_float_str_always_type_error(x):
    assume(not isinstance(x, int) or isinstance(x, bool))
    # floats and strs must raise TypeError; filter to those types
    if isinstance(x, (float, str)):
        with pytest.raises(TypeError):
            to_roman(x)

def test_to_roman_bool_is_type_not_value():
    # True == 1 but spec demands TypeError, not ValueError/success
    with pytest.raises(TypeError):
        to_roman(True)
    with pytest.raises(TypeError):
        to_roman(False)


# ---- to_roman range errors ----
@pytest.mark.parametrize("bad", [0, -1, -100, 4000, 4001, 10000, -2147483648])
def test_to_roman_out_of_range(bad):
    with pytest.raises(ValueError):
        to_roman(bad)

@given(st.integers())
def test_to_roman_out_of_range_property(n):
    assume(n < 1 or n > 3999)
    with pytest.raises(ValueError):
        to_roman(n)


# ---- from_roman type errors ----
@pytest.mark.parametrize("bad", [None, 1, 4, 0, True, False, 4.5, b"IV", ["X"], ("X",), 58])
def test_from_roman_type_errors(bad):
    with pytest.raises(TypeError):
        from_roman(bad)


# ---- from_roman value errors: spec-named boundaries ----
def test_from_roman_empty_raises():
    with pytest.raises(ValueError):
        from_roman("")

@pytest.mark.parametrize("s", ["iv", "Iv", "iV", "mcmxciv", "lviii"])
def test_from_roman_lowercase_raises(s):
    with pytest.raises(ValueError):
        from_roman(s)

@pytest.mark.parametrize("s", [" X", "X ", "X\n", "\tX", "X\n", "M CM", "M\tM", "\n", " ", "X X"])
def test_from_roman_whitespace_raises(s):
    with pytest.raises(ValueError):
        from_roman(s)

@pytest.mark.parametrize("s", ["IIII", "VV", "IC", "XM", "IXI", "MMMM", "XXXX", "CCCC", "LL", "DD",
                               "IIV", "VIV", "IXIX", "IVIV", "IL", "IM", "XD", "XM", "VX", "LC",
                               "DM", "MMMMM", "CMCM", "IXI", "MIM", "DCD", "XCXC", "II", "XXXX",
                               "VVV", "LLL", "DDD", "MMMM", "IIIIIIIII", "VIX", "IVX"])
def test_from_roman_noncanonical_raises(s):
    with pytest.raises(ValueError):
        from_roman(s)

@pytest.mark.parametrize("s", ["", "A", "Z", "0", "?", "M*", "X!", "IV.", "-IV", "+X", "MMMM", "MMMMM", "MMMMMMMMMM"])
def test_from_roman_unknown_chars_and_overflow(s):
    with pytest.raises(ValueError):
        from_roman(s)

def test_from_roman_rejects_all_single_unknown_chars():
    for ch in list(string.ascii_letters + string.digits + string.punctuation + " \t\n\r"):
        if ch in "IVXLCDM":
            continue
        with pytest.raises(ValueError):
            from_roman(ch)


# ---- strict inverse: membership property ----
@given(st.text(alphabet="IVXLCDM", min_size=1, max_size=6))
def test_from_roman_strict_inverse_random_over_alphabet(s):
    if s in CANONICAL_SET:
        assert from_roman(s) == CANONICAL_SET[s]
    else:
        with pytest.raises(ValueError):
            from_roman(s)

@given(st.text(alphabet="IVXLCDMivxlcdm 012 \n\tXZ", min_size=0, max_size=5))
def test_from_roman_strict_inverse_noisy_alphabet(s):
    if s in CANONICAL_SET:
        assert from_roman(s) == CANONICAL_SET[s]
    else:
        with pytest.raises(ValueError):
            from_roman(s)

def test_from_roman_accepts_exactly_canonical_set():
    # every canonical string accepted with right value
    for s, v in CANONICAL_SET.items():
        assert from_roman(s) == v
        assert to_roman(v) == s
    # spot-check near-misses are rejected
    for s in ["IIII", "VV", "LL", "DD", "MMMM", "", "iv", " X", "IC", "XM", "IXI"]:
        with pytest.raises(ValueError):
            from_roman(s)


# ---- canonical shape properties of to_roman ----
@given(st.integers(min_value=1, max_value=3999))
def test_to_roman_uses_only_allowed_subtractive_pairs(n):
    s = to_roman(n)
    # only IV, IX, XL, XC, CD, CM may appear as smaller-before-larger
    vals = {"I": 1, "V": 5, "X": 10, "L": 50, "C": 100, "D": 500, "M": 1000}
    for a, b in zip(s, s[1:]):
        if vals[a] < vals[b]:
            assert a + b in ("IV", "IX", "XL", "XC", "CD", "CM"), s

@given(st.integers(min_value=1, max_value=3999))
def test_to_roman_no_four_repeats(n):
    s = to_roman(n)
    for bad in ("IIII", "XXXX", "CCCC", "MMMM"):
        assert bad not in s

@given(st.integers(min_value=1, max_value=3999))
def test_to_roman_no_repeated_VLD(n):
    s = to_roman(n)
    for bad in ("VV", "LL", "DD"):
        assert bad not in s

@given(st.integers(min_value=1, max_value=3999))
def test_to_roman_charset(n):
    s = to_roman(n)
    assert s != ""
    assert all(c in "IVXLCDM" for c in s)
